import 'package:flutter/foundation.dart';

import '../../models/ai/scan_document_result.dart';
import '../../models/braille/braille_mode.dart';
import 'offline_braille_service.dart';

/// Translates a batch of UEB text lines into [mode], one result per line.
typedef UebLinesTranslator =
    Future<List<OfflineBrailleResult>> Function(
      List<String> lines,
      BrailleMode mode,
    );

/// Whether Braille 1 can be shown for a record.
enum BrailleModeAvailability {
  available,

  /// Braille 1 is generated by the on-device translator (Android only).
  unsupportedPlatform,

  /// An older record without per-block source text.
  noSourceText,

  /// Only math or tables (Nemeth Braille), which modes do not change.
  mathOnly,
}

/// Pages prepared for display in one Braille mode.
@immutable
class BrailleModeView {
  const BrailleModeView({
    required this.pages,
    required this.mode,
    this.fellBack = false,
  });

  /// Pages to display. In Braille 1, UEB blocks carry Braille 1 copies;
  /// the stored blocks are never changed.
  final List<DocumentPage> pages;

  /// The mode actually shown.
  final BrailleMode mode;

  /// True when Braille 1 was requested but could not be produced, so
  /// Braille 2 is shown instead.
  final bool fellBack;

  /// The combined Braille of [pages], joined like
  /// [ScanDocumentResult.combinedBraille].
  String get combinedBraille => ScanDocumentResult.combineBrailleOf(pages);
}

/// The mode a record's combined Braille was saved in (Braille 2 when the
/// blocks carry no saved mode).
BrailleMode savedBrailleModeOf(List<DocumentPage> pages) {
  for (final DocumentPage page in pages) {
    if (page.blocks.isNotEmpty) {
      return page.blocks.first.savedBrailleMode;
    }
  }

  return BrailleMode.defaultMode;
}

/// Produces Braille 1 for display from the Braille 2 records the scanners
/// return. Braille 2 is always the stored output and is returned untouched.
class BrailleModeTranslator {
  BrailleModeTranslator({
    UebLinesTranslator? translateLines,
    bool Function()? isSupported,
    this.batchSize = 64,
  }) : _translateLines = translateLines ?? _translateWithLiblouis,
       _isSupported = isSupported ?? _isAndroid;

  static final BrailleModeTranslator instance = BrailleModeTranslator();

  static const int _maximumCachedLines = 4000;

  final UebLinesTranslator _translateLines;
  final bool Function() _isSupported;

  /// Lines sent per platform call. Each call runs on the native background
  /// executor; awaiting between batches lets frames render.
  final int batchSize;

  /// Braille 1 of each source line already translated, so switching modes
  /// and reopening records is instant.
  final Map<String, String> _uncontractedLines = <String, String>{};

  static bool _isAndroid() {
    return !kIsWeb && defaultTargetPlatform == TargetPlatform.android;
  }

  static Future<List<OfflineBrailleResult>> _translateWithLiblouis(
    List<String> lines,
    BrailleMode mode,
  ) {
    return const OfflineBrailleService().translateUebLines(lines, mode: mode);
  }

  BrailleModeAvailability availabilityOf(List<DocumentPage> pages) {
    if (!_isSupported()) {
      return BrailleModeAvailability.unsupportedPlatform;
    }

    final Iterable<DocumentBlock> blocks = pages.expand(
      (DocumentPage page) => page.blocks,
    );

    if (blocks.any(_isTranslatable)) {
      return BrailleModeAvailability.available;
    }

    final bool hasMathBraille = blocks.any(
      (DocumentBlock block) => block.hasBraille && block.isNemethBraille,
    );

    return hasMathBraille
        ? BrailleModeAvailability.mathOnly
        : BrailleModeAvailability.noSourceText;
  }

  /// [pages] shown in [mode]. Never throws: if Braille 1 cannot be made,
  /// the Braille 2 pages are returned with [BrailleModeView.fellBack] set.
  Future<BrailleModeView> viewFor(
    List<DocumentPage> pages,
    BrailleMode mode,
  ) async {
    if (mode == BrailleMode.contracted) {
      return BrailleModeView(pages: pages, mode: BrailleMode.contracted);
    }

    final BrailleModeView fallback = BrailleModeView(
      pages: pages,
      mode: BrailleMode.contracted,
      fellBack: true,
    );

    if (availabilityOf(pages) != BrailleModeAvailability.available) {
      return fallback;
    }

    try {
      await _translateMissingLines(pages, mode);

      return BrailleModeView(
        pages: pages
            .map((DocumentPage page) {
              return DocumentPage(
                pageIndex: page.pageIndex,
                width: page.width,
                height: page.height,
                blocks: List<DocumentBlock>.unmodifiable(
                  page.blocks.map(_uncontractedBlock),
                ),
              );
            })
            .toList(growable: false),
        mode: mode,
      );
    } catch (error) {
      debugPrint('Braille 1 unavailable, showing Braille 2: $error');
      return fallback;
    }
  }

  /// Only UEB text with source text changes; Nemeth math and tables never
  /// do.
  static bool _isTranslatable(DocumentBlock block) {
    return block.isUebBraille &&
        block.hasBraille &&
        block.normalizedContent.trim().isNotEmpty;
  }

  /// Lines of the text the block's Braille was translated from. The online
  /// translator also works line by line, so line breaks match.
  static List<String> _sourceLines(DocumentBlock block) {
    return block.normalizedContent
        .split('\n')
        .map((String line) => line.trim())
        .where((String line) => line.isNotEmpty)
        .toList(growable: false);
  }

  Future<void> _translateMissingLines(
    List<DocumentPage> pages,
    BrailleMode mode,
  ) async {
    final List<String> missing = pages
        .expand((DocumentPage page) => page.blocks)
        .where(_isTranslatable)
        .expand(_sourceLines)
        .where((String line) => !_uncontractedLines.containsKey(line))
        .toSet()
        .toList(growable: false);

    final Map<String, String> translated = <String, String>{};

    for (int start = 0; start < missing.length; start += batchSize) {
      final List<String> batch = missing.sublist(
        start,
        start + batchSize > missing.length ? missing.length : start + batchSize,
      );

      final List<OfflineBrailleResult> results = await _translateLines(
        batch,
        mode,
      );

      if (results.length != batch.length) {
        throw const OfflineBrailleException(
          'Liblouis returned an incomplete translation.',
        );
      }

      for (int index = 0; index < batch.length; index++) {
        final OfflineBrailleResult result = results[index];

        if (!result.success || result.content.trim().isEmpty) {
          throw OfflineBrailleException(
            result.error ?? 'Liblouis returned an empty translation.',
          );
        }

        translated[batch[index]] = result.content.trim();
      }
    }

    // Cache only after every line succeeded.
    if (_uncontractedLines.length + translated.length > _maximumCachedLines) {
      _uncontractedLines.clear();
    }

    _uncontractedLines.addAll(translated);
  }

  DocumentBlock _uncontractedBlock(DocumentBlock block) {
    if (!_isTranslatable(block)) {
      return block;
    }

    return block.withBrailleContent(
      _sourceLines(
        block,
      ).map((String line) => _uncontractedLines[line]!).join('\n'),
    );
  }
}
